RSpec.describe RecoverInvoiceOperationIntentsJob, "after a crash under the timekeeping owner", committed_data: true do
  # "a crash between prepare and step 3 leaves the intent pending, and `RecoverInvoiceOperationIntentsJob` fails it and aborts;"
  it "fails a pending intent whose prepare the remote Timekeeping applied before a crash, and its abort frees the entry there" do
    company = create(:company)
    project = create(:project, client: create(:client, company:), billable: true)
    user = create(:user, current_workspace_id: company.id)
    row = create(:timesheet_entry, user:, project:, bill_status: "unbilled")
    TimekeepingOwnership.current.update!(owner: "timekeeping", handoff_step: nil)
    generation = TimekeepingOwnership.current.generation

    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    fake.generation = generation
    fake.add_entry(company_id: company.id, user_id: user.id, project_id: project.id, id: row.id)
    credential = lambda do |company_id:, operation:|
      Timekeeping::ServiceToken.mint(company_id:, operations: [operation], private_key: timekeeping_key_pair)
    end
    client = Timekeeping::ReservationClient.new(
      http: TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil), credential:
    )
    request = Invoices::ReservationRequest.new(company_id: company.id, invoice_id: 9_101, operation_id: SecureRandom.uuid,
                                               generation:, disposition: "active", entries: [row.id])
    InvoiceOperationIntent.create!(company_id: company.id, invoice_id: 9_101, operation_id: request.operation_id,
                                   state: "pending", generation:, disposition: "active",
                                   desired_entry_ids: [row.id], created_at: 5.minutes.ago)

    # The save prepared on Timekeeping, then the process died before step 3.
    ApplicationRecord.transaction { expect(client.prepare(request).state).to eq("prepared") }
    expect(fake.entry_locked?(row.id)).to be(true)

    described_class.perform_now(reservations: client)

    expect(InvoiceOperationIntent.find_by!(operation_id: request.operation_id).state).to eq("failed")
    abort_rows = InvoiceOperationOutboxItem.where(company_id: company.id, operation_id: request.operation_id)
    expect(abort_rows.pluck(:kind)).to eq(["abort"])
    expect(abort_rows.first.delivered_at).to be_present
    expect(fake.reservations_for(row.id)).to eq([])
    expect(fake.entry_locked?(row.id)).to be(false)
  end
end

RSpec.describe RecoverInvoiceOperationIntentsJob, "with an undeliverable outbox row" do
  def recovery_undeliverable_abort_row(company_id)
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(company_id:, invoice_id: 1, operation_id:, state: "failed", generation: 1,
                                   disposition: "active", desired_entry_ids: [1], created_at: 1.minute.ago)
    InvoiceOperationOutboxItem.record!(kind: "abort", company_id:, invoice_id: 1, operation_id:, generation: 1,
                                       disposition: "active", desired_entry_ids: [1])
  end

  it "never hands a row marked undeliverable to delivery, while still delivering the other undelivered rows" do
    stale_id = recovery_undeliverable_abort_row(7801)
    InvoiceOperationOutboxItem.where(id: stale_id).update_all(undeliverable_at: Time.current)
    live_id = recovery_undeliverable_abort_row(7801)
    delivered_ids = []
    allow(DeliverInvoiceOperationJob).to receive(:perform_now) { |outbox_item_id, **| delivered_ids << outbox_item_id }
    aborted = Invoices::ReservationOutcome.new(state: "aborted", conflicts: [], counts: {})

    described_class.perform_now(reservations: RecordingReservationAdapter.new(prepare: aborted, commit: aborted, abort: aborted))

    expect(delivered_ids).to eq([live_id])
    stale = InvoiceOperationOutboxItem.find(stale_id)
    expect(stale.delivered_at).to be_nil
    expect(stale.attempts).to eq(0)
  end
end
